public class AgentStepTrace
{
    public int StepNumber { get; set; }
    public DateTimeOffset Timestamp { get; set; }
    public ChatMessage Thought { get; set; }  // LLM reasoning output
    public FunctionCallContent Action { get; set; }  // Tool call decision
    public string Observation { get; set; }  // Tool result
    public TimeSpan Duration { get; set; }
    public Dictionary<string, object> Metadata { get; set; }
}

public class TracedAgent
{
    private readonly List<AgentStepTrace> _trace = new();

    public async Task<string> RunAsync(string userGoal)
    {
        var conversation = new List<ChatMessage> { new(ChatRole.User, userGoal) };

        for (int step = 0; step < MaxIterations; step++)
        {
            var stepStart = Stopwatch.StartNew();

            // Record the full prompt that went to the LLM
            var requestMsg = CloneConversation(conversation);

            var completion = await _client.CompleteAsync(conversation);

            var functionCalls = completion.Message.Contents
                .OfType<FunctionCallContent>().ToList();

            if (!functionCalls.Any())
            {
                // Final answer — record and return
                _trace.Add(new AgentStepTrace
                {
                    StepNumber = step,
                    Timestamp = DateTimeOffset.UtcNow,
                    Thought = requestMsg, // What we sent
                    Action = null, // No tool call
                    Observation = completion.Message.Text,
                    Duration = stepStart.Elapsed
                });
                return completion.Message.Text;
            }

            // Execute tool calls and capture observations
            foreach (var call in functionCalls)
            {
                var toolResult = await ExecuteToolAsync(call);

                _trace.Add(new AgentStepTrace
                {
                    StepNumber = step,
                    Timestamp = DateTimeOffset.UtcNow,
                    Thought = requestMsg,
                    Action = call,
                    Observation = toolResult,
                    Duration = stepStart.Elapsed,
                    Metadata = new Dictionary<string, object>
                    {
                        ["token_usage"] = completion.Usage,
                        ["temperature"] = 0.1
                    }
                });

                conversation.Add(new(ChatRole.Tool, toolResult));
            }
        }
        return string.Empty;
    }

    public void ExportTrace(string sessionId) =>
        _trace.ToJsonFile($"traces/{sessionId}.json");
}

[ApiController]
[Route("api/agent/replay/{sessionId}")]
public class AgentReplayController : ControllerBase
{
    private readonly IAgentTraceStore _traces;

    [HttpGet]
    public async Task<IActionResult> GetReplay(string sessionId, [FromQuery] int? highlightStep = null)
    {
        var trace = await _traces.GetAsync(sessionId);
        if (trace == null) return NotFound();

        var replay = new AgentReplay
        {
            SessionId = sessionId,
            Steps = trace.Steps.Select(s => new ReplayStep
            {
                StepNumber = s.StepNumber,
                Thought = s.Thought,
                Action = s.Action?.Name,
                ActionArgs = s.Action?.Arguments,
                Observation = Truncate(s.Observation, 500),
                DurationMs = (int)s.Duration.TotalMilliseconds,
                Success = s.Action == null ? true : s.Observation.Contains("error", StringComparison.OrdinalIgnoreCase) == false
            }).ToList()
        };

        return Ok(new { replay, highlightedStep = highlightStep });
    }

    [HttpPost("simulate")]
    public async Task<IActionResult> Simulate(string sessionId, [FromBody] SimulatedToolResult simulated)
    {
        var trace = await _traces.GetAsync(sessionId);
        var replayed = await ReplayWithOverrideAsync(trace, simulated);
        return Ok(replayed);
    }
}
